'use strict';
// PLAY11 technical behavior tests for the two market fixture silhouettes
// (stock rack vs cold-room fixture) and their honest power-state rendering.
// The real backstage-core.js drives geometry/state; a recording canvas observes
// actual Canvas2D calls from real BackstageScene.draw. Synthetic position and
// inventory setups below are labelled technical fixtures and are not natural
// gameplay evidence (parent owns GUI / natural-run acceptance).
const test=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const path=require('node:path');
const B=require('./backstage-core.js');
const SCENE_SRC=fs.readFileSync(path.join(__dirname,'backstage-scene.js'),'utf8');

// Strict recording 2D context: numeric arguments must be finite, rects/texts are
// captured in transformed coordinates, save/translate/scale/restore implement
// real Canvas post-multiplication (adapted from test-night-map-scene.js).
function recorder(){
  const calls=[],rects=[],shapes=[],texts=[];
  const stack=[];
  let m=[1,0,0,1,0,0];
  let verts=null,pending=null,closed=false;
  const need=(v,what)=>{
    if(typeof v!=='number'||!Number.isFinite(v))throw new Error('invalid canvas numeric argument '+what+': '+String(v));
    return v;
  };
  const ap=(x,y)=>[m[0]*x+m[2]*y+m[4],m[1]*x+m[3]*y+m[5]];
  const flush=(mode)=>{
    if(pending&&pending.kind==='ellipse'){
      shapes.push({type:'ellipse',mode,x:pending.x,y:pending.y,rx:pending.rx,ry:pending.ry,
        color:mode==='fill'?ctx.fillStyle:ctx.strokeStyle,lineWidth:ctx.lineWidth});
    }else if(verts&&verts.length>=2){
      shapes.push({type:'path',mode,closed,verts:verts.map(p=>({x:p[0],y:p[1]})),
        color:mode==='fill'?ctx.fillStyle:ctx.strokeStyle,lineWidth:ctx.lineWidth});
    }
    pending=null;
  };
  const ctx={
    fillStyle:'#000000',strokeStyle:'#000000',lineWidth:1,font:'10px sans-serif',textAlign:'left',globalAlpha:1,
    save(){calls.push(['save']);stack.push(m.slice());},
    restore(){calls.push(['restore']);if(stack.length)m=stack.pop();else throw new Error('restore without save');},
    translate(tx,ty){need(tx,'translate.tx');need(ty,'translate.ty');calls.push(['translate',tx,ty]);
      const a=m[0],b=m[1],c=m[2],d=m[3];m[4]+=a*tx+c*ty;m[5]+=b*tx+d*ty;},
    scale(sx,sy){need(sx,'scale.sx');need(sy,'scale.sy');calls.push(['scale',sx,sy]);m[0]*=sx;m[1]*=sx;m[2]*=sy;m[3]*=sy;},
    clearRect(x,y,w,h){[x,y,w,h].forEach((v,i)=>need(v,'clearRect'+i));calls.push(['clearRect',x,y,w,h]);
      const [X,Y]=ap(x,y);rects.push({mode:'clear',x:X,y:Y,w:w*m[0],h:h*m[3]});},
    fillRect(x,y,w,h){[x,y,w,h].forEach((v,i)=>need(v,'fillRect'+i));calls.push(['fillRect',x,y,w,h]);
      const [X,Y]=ap(x,y);rects.push({mode:'fill',x:X,y:Y,w:w*m[0],h:h*m[3],color:ctx.fillStyle});},
    strokeRect(x,y,w,h){[x,y,w,h].forEach((v,i)=>need(v,'strokeRect'+i));calls.push(['strokeRect',x,y,w,h]);
      const [X,Y]=ap(x,y);rects.push({mode:'stroke',x:X,y:Y,w:w*m[0],h:h*m[3],color:ctx.strokeStyle,lineWidth:ctx.lineWidth});},
    beginPath(){calls.push(['beginPath']);verts=[];pending=null;closed=false;},
    moveTo(x,y){need(x,'moveTo.x');need(y,'moveTo.y');calls.push(['moveTo',x,y]);verts.push(ap(x,y));},
    lineTo(x,y){need(x,'lineTo.x');need(y,'lineTo.y');calls.push(['lineTo',x,y]);if(verts)verts.push(ap(x,y));},
    closePath(){calls.push(['closePath']);closed=true;},
    ellipse(x,y,rx,ry){[x,y,rx,ry].forEach((v,i)=>need(v,'ellipse'+i));calls.push(['ellipse',x,y,rx,ry]);
      const [X,Y]=ap(x,y);pending={kind:'ellipse',x:X,y:Y,rx:rx*Math.hypot(m[0],m[1]),ry:ry*Math.hypot(m[2],m[3])};},
    arc(x,y,r){[x,y,r].forEach((v,i)=>need(v,'arc'+i));calls.push(['arc',x,y,r]);
      const [X,Y]=ap(x,y);pending={kind:'ellipse',x:X,y:Y,rx:r*Math.hypot(m[0],m[1]),ry:r*Math.hypot(m[0],m[1])};},
    fill(){calls.push(['fill']);flush('fill');},
    stroke(){calls.push(['stroke']);flush('stroke');},
    fillText(t,x,y){need(x,'fillText.x');need(y,'fillText.y');calls.push(['fillText',String(t),x,y]);
      const [X,Y]=ap(x,y);texts.push({text:String(t),x:X,y:Y,font:ctx.font,color:ctx.fillStyle,align:ctx.textAlign});},
    setLineDash(){calls.push(['setLineDash']);},
    createLinearGradient(x0,y0,x1,y1){[x0,y0,x1,y1].forEach((v,i)=>need(v,'gradient'+i));return{addColorStop(){}};},
    createRadialGradient(x0,y0,r0,x1,y1,r1){[x0,y0,r0,x1,y1,r1].forEach((v,i)=>need(v,'radialGradient'+i));
      return{addColorStop(){}};}
  };
  return Object.assign(ctx,{calls,rects,shapes,texts,_stack:stack,matrix:()=>m.slice()});
}
function load(width=860,reduced=false){
  const rec=recorder();
  const canvas={getContext:()=>rec,getBoundingClientRect:()=>({width,height:560,left:0,top:0})};
  const sandbox={Backstage:B,matchMedia:()=>({matches:reduced})};
  sandbox.window=sandbox;
  vm.createContext(sandbox);
  vm.runInContext(SCENE_SRC,sandbox,{filename:'backstage-scene.js'});
  return {rec,scene:new sandbox.BackstageScene(canvas)};
}
function render(r,o={}){
  const width=o.width??860,overview=o.overview??false,reduced=o.reduced??false;
  const {rec,scene}=load(width,reduced);
  scene.draw(r,{overview});
  assert.equal(rec._stack.length,0,'draw must balance save/restore');
  assert.deepEqual(rec.matrix(),[1,0,0,1,0,0],'draw must finish in identity screen space');
  return {rec,scene,view:scene.camera(r,overview)};
}

// Real run builders: marketShift is strict opt-in; ordinary create() stays legacy.
const shift=(day=1,seed=42)=>B.create(seed,day,'hook',[],{marketShift:true});
// Map the two real shelf-kind WALLS to market rooms purely by center-in-room geometry.
function shelfMap(){
  const info=B.locationInfo(shift(1));
  assert.equal(info.enabled,true);
  const byRoom={};
  for(const w of B.WALLS.filter(q=>q.kind==='shelf')){
    const cx=w.x+w.w/2,cy=w.y+w.h/2;
    const room=info.rooms.find(rm=>(rm.id==='market-stock'||rm.id==='market-cold')&&
      cx>=rm.x&&cx<=rm.x+rm.w&&cy>=rm.y&&cy<=rm.y+rm.h);
    if(room)byRoom[room.id]=w;
  }
  return byRoom;
}
// Contract envelope declared by the plan: the silhouettes must stay inside the
// old fixture visual envelope x..x+w+15, y-36..y+h+10.
const env=w=>({x:w.x,y:w.y-36,w:w.w+15,h:w.h+46});
const centerIn=(x,y,e)=>x>=e.x&&x<=e.x+e.w&&y>=e.y&&y<=e.y+e.h;
function worldRects(rec,v,w){
  const e=env(w);
  return rec.rects.filter(q=>q.mode==='fill').map(q=>({
    x:(q.x-v.x)/v.scale,y:(q.y-v.y)/v.scale,w:q.w/v.scale,h:q.h/v.scale,color:q.color
  })).filter(r=>centerIn(r.x+r.w/2,r.y+r.h/2,e));
}
function worldEllipses(rec,v,w){
  const e=env(w);
  return rec.shapes.filter(s=>s.type==='ellipse').map(s=>({
    x:(s.x-v.x)/v.scale,y:(s.y-v.y)/v.scale,rx:s.rx/v.scale,ry:s.ry/v.scale,
    color:s.color,mode:s.mode
  })).filter(s=>centerIn(s.x,s.y,e));
}
function worldTexts(rec,v,w){
  const e=env(w);
  return rec.texts.map(t=>({text:t.text,x:(t.x-v.x)/v.scale,y:(t.y-v.y)/v.scale}))
    .filter(t=>centerIn(t.x,t.y,e));
}
const R=5,round1=n=>Math.round(n*10**R)/10**R;
const rectKey=r=>[round1(r.x),round1(r.y),round1(r.w),round1(r.h),String(r.color)];
const ellipseKey=s=>[round1(s.x),round1(s.y),round1(s.rx),round1(s.ry),String(s.color),s.mode];
const sameDraw=(a,b)=>JSON.stringify(a.map(rectKey))===JSON.stringify(b.map(rectKey));
// Structural feature extractors describe silhouette construction (frame vs solid
// cabinet), not colors or source/helper names.
function stockFeatures(rects,w){
  const painted=rects.filter(r=>typeof r.color==='string');
  const broad=painted.filter(r=>r.h<=9&&r.w>=0.7*w.w&&r.y>=w.y-34&&r.y<=w.y+w.h+2);
  const tall=painted.filter(r=>r.w<=10&&r.h>=40&&r.h>=3*r.w);
  const clusters=[];
  for(const r of tall){const c=r.x+r.w/2;if(!clusters.some(q=>Math.abs(q.x-c)<=8))clusters.push({x:c,top:r.y,bottom:r.y+r.h});
    else{const q=clusters.find(q=>Math.abs(q.x-c)<=8);q.top=Math.min(q.top,r.y);q.bottom=Math.max(q.bottom,r.y+r.h);}}
  const body=painted.find(r=>r.w>=w.w-2&&r.h>=w.h+18);
  const area=painted.reduce((n,r)=>n+r.w*r.h,0)/(env(w).w*env(w).h);
  return {broadCount:broad.length,bandTops:new Set(broad.map(r=>round1(r.y))).size,
    uprights:clusters,solidBody:Boolean(body),areaRatio:area};
}
function coldFeatures(rects,ells,w){
  const painted=rects.filter(r=>typeof r.color==='string');
  const mid=w.x+w.w/2;
  const body=painted.find(r=>r.w>=w.w-2&&r.h>=w.h+20);
  const panels=painted.filter(r=>r.w>=0.32*w.w&&r.w<=0.56*w.w&&r.h>=40&&
    r.y>=w.y-26&&r.y<=w.y+42&&Math.abs((r.x+r.w/2)-mid)>=0.15*w.w);
  const seam=painted.find(r=>r.w<=5&&r.h>=50&&Math.abs((r.x+r.w/2)-mid)<=4);
  const handles=painted.filter(r=>r.w<=5&&r.h>=12&&r.h<=30&&Math.abs((r.x+r.w/2)-mid)<=18);
  const slots=painted.filter(r=>r.h<=7&&r.w>=0.7*w.w&&r.y>=w.y+44);
  const slotRows=new Set(slots.map(r=>round1(r.y)));
  // The state light is the only small ellipse riding the top housing strip.
  const light=ells.find(s=>s.mode==='fill'&&s.rx<=6&&s.ry<=6&&
    s.x>=w.x+w.w-40&&s.x<=w.x+w.w&&s.y>=w.y-36&&s.y<=w.y-18);
  return {body:body?{x:body.x,y:body.y,w:body.w,h:body.h}:null,
    panelCount:panels.length,panels,seam:Boolean(seam),handles:handles.length,
    slotRows:slotRows.size,light};
}
// Generic legacy shelf: repeated narrow upright slats over a solid box body.
function genericSlatCount(rects,w){
  return rects.filter(r=>typeof r.color==='string'&&r.w>=15&&r.w<=20&&
    r.h>=w.h-19&&r.h<=w.h-15&&r.y>=w.y).length;
}
function restoredLegacy(version){
  const r=B.create(11,1);
  r.version=version;
  delete r.district;
  if(version<3)delete r.location;
  if(version===1)delete r.street;
  const restored=B.restore(r);
  assert.ok(restored,'real B.restore must accept the legacy v'+version+' fixture');
  return restored;
}
// Technical movement: walk straight with real stepping, staying on legal cells.
function walkTo(r,to){
  for(let n=0;n<6000&&Math.hypot(to.x-r.p.x,to.y-r.p.y)>4;n++){
    const d=Math.hypot(to.x-r.p.x,to.y-r.p.y);
    B.step(r,{dx:(to.x-r.p.x)/d,dy:(to.y-r.p.y)/d},.025);
    assert.ok(!B.solid(r,r.p.x,r.p.y));
  }
  assert.ok(Math.hypot(to.x-r.p.x,to.y-r.p.y)<=6,JSON.stringify({p:r.p,to}));
}

test('real geometry: exactly two shelf walls, centered one each in market-stock and market-cold rooms',()=>{
  const shelves=B.WALLS.filter(w=>w.kind==='shelf');
  assert.equal(shelves.length,2);
  const map=shelfMap();
  assert.ok(map['market-stock']&&map['market-cold'],'both real shelves map to market rooms by geometry');
  assert.notDeepEqual(map['market-stock'],map['market-cold']);
  // The pickups live outside the shelf envelopes (fixtures must not cover them).
  assert.equal(B.solid(shift(1),405,990),false);
  assert.equal(B.solid(shift(1),740,850),false);
});

test('stock fixture draws an open rack frame: broad tier edges, separated uprights, no solid box',()=>{
  const r=shift(1);assert.equal(B.marketInfo(r).enabled,true);
  const w=shelfMap()['market-stock'];
  const {rec,view}=render(r);
  const rects=worldRects(rec,view,w);
  const f=stockFeatures(rects,w);
  assert.ok(f.bandTops>=3,'need at least 3 distinct broad horizontal tier edges, got '+f.bandTops);
  assert.ok(f.broadCount>=4,'broad tier/plinth edges spanning the rack, got '+f.broadCount);
  assert.ok(f.uprights.length>=3,'separated upright supports, got '+f.uprights.length);
  assert.ok(f.uprights.length<=4,'open frame bays, not a run of slats, got '+f.uprights.length);
  const xs=f.uprights.map(q=>q.x);
  assert.ok(Math.max(...xs)-Math.min(...xs)>=0.6*w.w,'supports must be separated across the width');
  assert.ok(Math.min(...f.uprights.map(q=>q.top))<=w.y-28,'uprights rise to the top tier');
  assert.ok(Math.max(...f.uprights.map(q=>q.bottom))>=w.y+w.h-8,'uprights reach the base');
  assert.equal(f.solidBody,false,'open rack must not render a wardrobe-style solid box');
  assert.ok(f.areaRatio<=0.65,'open bays dominate the rack silhouette, area ratio '+f.areaRatio.toFixed(2));
  assert.equal(worldTexts(rec,view,w).length,0,'fixtures promise no new text');
});

test('cold fixture draws a solid insulated cabinet: doors, center seam, handles, lower grille',()=>{
  const r=shift(1);
  const w=shelfMap()['market-cold'];
  const {rec,view}=render(r);
  const f=coldFeatures(worldRects(rec,view,w),worldEllipses(rec,view,w),w);
  assert.ok(f.body,'solid cabinet body required');
  assert.ok(f.body.w>=w.w&&f.body.h>=w.h+20);
  assert.equal(f.panelCount,2,'two closed door panels, got '+f.panelCount);
  const pcx=f.panels.map(q=>q.x+q.w/2).sort((a,b)=>a-b),mid=w.x+w.w/2;
  assert.ok(pcx[0]<mid&&pcx[1]>mid,'door panels sit on opposite sides of the center seam');
  assert.equal(f.seam,true,'center door seam required');
  assert.ok(f.handles>=2,'paired door handles required, got '+f.handles);
  assert.ok(f.slotRows>=3,'broad ventilation grille rows on the lower front, got '+f.slotRows);
  assert.ok(f.light,'power-state housing light required');
  assert.equal(worldTexts(rec,view,w).length,0,'fixtures promise no new text');
});

test('rack and cold cabinet are structurally distinct silhouettes even with color ignored',()=>{
  const r=shift(1);
  const map=shelfMap();
  const {rec,view}=render(r);
  const s=stockFeatures(worldRects(rec,view,map['market-stock']),map['market-stock']);
  const c=coldFeatures(worldRects(rec,view,map['market-cold']),worldEllipses(rec,view,map['market-cold']),map['market-cold']);
  assert.notEqual(s.solidBody,Boolean(c.body),'one open frame, one solid cabinet');
  assert.ok(s.uprights.length-c.uprightCount()>=2,'rack has multiple open-frame supports, cabinet does not');
  assert.ok(c.panelCount===2&&c.seam&&c.handles>=2&&c.slotRows>=3,'cabinet-only door/grille structure');
  assert.ok(c.light&&!worldEllipses(rec,view,map['market-stock']).some(e=>e.rx<=6&&e.y<map['market-stock'].y-18),
    'state light belongs to the cold fixture only');
});

test('power state is honest: lit while powered, dark during blackout, lit again after the real repair command',()=>{
  // Technical fixtures: actors removed; real B.create states and real B.command
  // repair sequence (walk-collect part, walk to fuse, market-power).
  const map=shelfMap(),w=map['market-cold'];
  const lightOf=r=>{
    const {rec,view}=render(r);
    const f=coldFeatures(worldRects(rec,view,w),worldEllipses(rec,view,w),w);
    assert.ok(f.light,'state light rendered');
    const glowAt=worldRects(rec,view,w).filter(q=>typeof q.color!=='string'&&
      Math.hypot(q.x+q.w/2-f.light.x,q.y+q.h/2-f.light.y)<=14).length;
    return {color:f.light.color,glow:glowAt,painted:worldRects(rec,view,w).filter(q=>typeof q.color==='string')};
  };
  const staffed=shift(1);staffed.actors=[];
  assert.equal(B.marketInfo(staffed).condition,'staffed');
  assert.equal(B.marketInfo(staffed).powered,true);
  const restock=shift(2);restock.actors=[];
  assert.equal(B.marketInfo(restock).condition,'restock');
  assert.equal(B.marketInfo(restock).powered,true);
  const black=shift(3);black.actors=[];
  assert.equal(B.marketInfo(black).condition,'blackout');
  assert.equal(B.marketInfo(black).powered,false);
  // Cold goods really stay locked while unpowered (gameplay semantics unchanged).
  assert.equal(B.command(black,'collect',{itemId:'item1'}),false,'cannot grab cold goods from afar');
  Object.assign(black.p,{x:740,y:850});
  assert.equal(B.command(black,'collect',{itemId:'item1'}),false,'cold stock refuses even standing on it');

  const lit=lightOf(staffed),alsoLit=lightOf(restock),dark=lightOf(black);
  assert.ok(lit.glow>=1,'powered light carries a cool glow');
  assert.equal(lit.color,alsoLit.color,'staffed and restock share the powered light');
  assert.notEqual(lit.color,dark.color,'blackout light must differ from powered');
  assert.equal(dark.glow,0,'unpowered blackout emits no false energy glow');
  assert.ok(sameDraw(lit.painted,dark.painted),'power changes only the state light, not the cabinet body');

  // Real repair, mirroring the adopted blackout regression excerpt.
  const r=shift(3);r.actors=[];
  assert.equal(B.marketInfo(r).powered,false);
  walkTo(r,{x:680,y:1142});
  assert.equal(B.command(r,'collect',{itemId:'item3'}),true,'real collect of the unloading salvage part');
  walkTo(r,{x:700,y:1105});
  assert.equal(B.command(r,'market-power'),true,'real fuse repair consumes the part');
  assert.equal(r.marketShift.powerItem,'item3');
  assert.equal(B.marketInfo(r).powered,true);
  assert.equal(B.command(r,'market-power'),false,'no free second repair');
  const repaired=lightOf(r);
  assert.equal(repaired.color,lit.color,'after real repair the same powered light returns');
  assert.ok(repaired.glow>=1,'repaired light glows again');
  assert.ok(sameDraw(repaired.painted,lit.painted),'repaired cabinet renders identically to staffed');
  // Technical repaired fixture survives real restore round-trip.
  assert.deepEqual(B.restore(r),r);
});

test('non-shift runs keep the unchanged generic shelf drawing (legacy fallback honest)',()=>{
  const r=B.create(42,1); // strict opt-out: no marketShift on a natural create()
  assert.equal(B.marketInfo(r).enabled,false);
  const map=shelfMap();
  const {rec,view}=render(r);
  for(const id of ['market-stock','market-cold']){
    const w=map[id],rects=worldRects(rec,view,w);
    assert.ok(genericSlatCount(rects,w)>=5,id+' keeps the generic repeated slats');
    assert.ok(rects.some(q=>q.color==='#526573'&&Math.abs(q.w-w.w)<1&&Math.abs(q.h-(w.h+22))<1),
      id+' keeps the generic solid box body');
    assert.equal(coldFeatures(rects,worldEllipses(rec,view,w),w).light,null,id+' shows no false power light');
  }
});

test('restored v1/v2/v3 legacy saves keep the generic shelf path and never crash full draw',()=>{
  const map=shelfMap();
  for(const version of [1,2,3]){
    const r=restoredLegacy(version);
    assert.equal(B.marketInfo(r).enabled,false);
    const {rec,view}=render(r);
    for(const id of ['market-stock','market-cold']){
      const w=map[id];
      assert.ok(genericSlatCount(worldRects(rec,view,w),w)>=5,'v'+version+' '+id+' generic slats');
      assert.equal(coldFeatures(worldRects(rec,view,w),worldEllipses(rec,view,w),w).light,null);
    }
  }
});

test('shelf branch needs real room containment plus enabled location+market; outside shelves stay generic',()=>{
  const r=shift(1),info=B.locationInfo(r),market=B.marketInfo(r);
  const {rec,scene}=load();
  assert.equal(rec,scene.c);
  const stock=shelfMap()['market-stock'];
  // Synthetic shelf far outside the market rooms with fully enabled context.
  const outside={x:1200,y:900,w:140,h:80,kind:'shelf'};
  scene.block(outside,info,market);
  assert.ok(genericSlatCount(worldRects(rec,{scale:1,x:0,y:0},outside),outside)>=5,'out-of-room shelf stays generic');
  // Missing/disabled context and legacy zero-arg calls keep the original path.
  scene.block(stock);
  assert.ok(genericSlatCount(worldRects(rec,{scale:1,x:0,y:0},stock),stock)>=5,'no-arg block stays generic');
  scene.block(stock,{enabled:false,rooms:[]},{enabled:false});
  // Positive control: the real stock shelf through the real branch is the open frame.
  const rec2=recorder();
  const ctxScene=Object.create(scene);
  // Direct identity-space dispatch on the same scene is sufficient and crash-safe.
  scene.block(stock,info,market);
  const rects=worldRects(rec,{scale:1,x:0,y:0},stock);
  assert.ok(stockFeatures(rects,stock).uprights.length>=3,'enabled in-room shelf uses the rack frame');
  assert.equal(rec._stack.length,0);
});

test('draw never mutates run state and fixture rendering is deterministic over time and reduced motion',()=>{
  const map=shelfMap();
  const fresh=()=>{const r=shift(3);r.actors=[];return r;};
  for(const setup of ['staffed','blackout']){
    const r=setup==='staffed'?(fresh(),shift(1)):fresh();
    if(setup==='staffed')r.actors=[];
    const before=structuredClone(r);
    const a=render(r).rec.calls,b=render(r).rec.calls;
    assert.deepEqual(a,b,'identical calls across draws');
    render(r,{width:390});render(r,{overview:true});render(r,{reduced:true});
    assert.deepEqual(r,before,'full draw is read-only');
  }
  // Fixture geometry is independent of clock: technical time jump changes nothing
  // inside either fixture envelope.
  const r=shift(1);r.actors=[];
  const pick=(run)=>{
    const {rec,view}=render(run);
    return [map['market-stock'],map['market-cold']].map(w=>({
